patchedWorkerFactory:
create() {
  // marimo resolves notebook_location() two levels above the assets entry.
  const pageUrl = new URL(window.location.href);
  const pageName = pageUrl.pathname.split("/").pop() || "index.html";
  const pageStem = pageName.replace(/\.[^.]*$/, "") || "index";
  const workerEntry = `${pageStem}_files/assets/quarto-marimo-worker.js`;
  return new Worker(new URL(workerEntry, pageUrl), {
    type: "module",
    name: this.name
  });
}

